{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California tenant screening fee cap (2026)","requirement":"A landlord may charge no more than the annual state cap for screening a prospective tenant, must give a receipt and itemized cost list and a copy of any credit report, refund unused amounts, and use a reusable screening report the tenant provides.","key_value":"$68.96 maximum screening fee for 2026","coverage_conditions":"Prospective tenants of residential rental units; no screening fee may be charged when no rental unit is actually available, and fees must be returned to applicants not selected unless an order-of-review policy applies.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Prospective tenants of residential rental units"},"exemptions":null,"penalty":null,"effective_date":"2026","citation":"Cal. Civ. Code § 1950.6","quoted_span":"The maximum tenant screening fee for 2026 is $68.96","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley tenant screening fee disclosure and renewal fee ban (ch. 13.78)","requirement":"An owner who charges a screening fee must give the applicant a tenant screening fee rights statement and the state maximum fee cap, and may not charge an existing tenant a non-refundable fee to renew a tenancy or to change a roommate.","key_value":null,"coverage_conditions":"All residential rental agreements in Berkeley; applies to owners and their agents who charge screening fees or renew tenancies, regardless of any contrary lease language.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Owners and agents of residential rental property in Berkeley"},"exemptions":null,"penalty":"Any provision of an existing rental agreement or lease that violates the chapter is unenforceable.","effective_date":null,"citation":"Berkeley Mun. Code ch. 13.78","quoted_span":"An owner of residential rental property (or the owner’s agent) cannot charge a non-refundable fee to any existing tenant for the purpose of renewing a tenancy, in whole or in part, including any fee associated with the departure of a roommate or to request to add or replace a roommate in a pre-existing household.","interaction":"Berkeley ordinance requires disclosure of the maximum fee cap permitted under California Civil Code Section 1950.6(b).","confidence":0.8,"conflict_flag":false,"conflict_note":null}
